EZTR_Basic_ReplaceText(0x074D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tudo certo! A Sociedade Secreta|11de Justica dos Bombers para sempre!|19", NULL);
EZTR_Basic_ReplaceText(0x074E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce decorou o |01codigo|00?|11Se voce fosse humano... entao eu|11poderia te tornar um membro dos|11|01Bombers|00... Que pena!|19", NULL);
EZTR_Basic_ReplaceText(0x074F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce e muito bom para|11um Deku Scrub!|11|12Se voce fosse humano...|11|12Entao eu poderia te dar um|11|01Caderno dos Bombers|00 original e te fazer|11um membro...|11|12O que voces acham, pessoal?|19", NULL);
EZTR_Basic_ReplaceText(0x0750, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nem pensar! Nada de Scrubs!|19", NULL);
EZTR_Basic_ReplaceText(0x0751, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Acho que nao... Uma vez deixamos|11um garoto que nao era humano entrar|11na gangue, e nos arrependemos muito!|11Foi mal!|10Mas vou te ensinar o |01codigo|00, como|11prometi. Mas so posso te contar|11|01uma vez|00, entao preste bem|11atencao!|10Pronto?|19", NULL);
EZTR_Basic_ReplaceText(0x0752, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O codigo e |01|00!|11A entrada para nosso |01esconderijo|00 esta em|11|01East Clock Town|00!|19", NULL);
EZTR_Basic_ReplaceText(0x0753, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Foi voce quem estourou aquilo|11la em cima?|11Uau!|19", NULL);
EZTR_Basic_ReplaceText(0x0754, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei, so pra voce, cara, eu posso te fazer|11um membro da nossa gangue, os|11|01Bombers|00!|19", NULL);
EZTR_Basic_ReplaceText(0x0755, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas tem um teste pra se tornar|11um membro dos |01Bombers|00. Vamos la!|11Tente!|19", NULL);
