EZTR_Basic_ReplaceText(0x077B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, nao... Me desculpe...|11Voce nao tem rupias |06suficientes|00...|BF", NULL);

EZTR_Basic_ReplaceText(0x077C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Umm... Nao quer tentar de novo?|19", NULL);
EZTR_Basic_ReplaceText(0x077D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tudo bem. O tempo acabou!|BF", NULL);
