EZTR_Basic_ReplaceText(0x0868, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh! Obrigada pelo que voce fez|11mais cedo!|11|12Como oferta especial so pra voce, vou|11deixar voce fazer esse passeio de graça.|19", NULL);
EZTR_Basic_ReplaceText(0x0869, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, mas espere... Sim. Como eu|11suspeitava...|19", NULL);
EZTR_Basic_ReplaceText(0x086A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Parece que o pantano envenenado foi|11limpo, entao por que nao tentar algo|11mais interessante?|19", NULL);

