EZTR_Basic_ReplaceText(0x086F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pronto?|11La vamos nos!|BF", NULL);
EZTR_Basic_ReplaceText(0x0870, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tee-hee-hee-hee!|11Entao voce quer tentar?|11A velha enxerga tudo!|19", NULL);
EZTR_Basic_ReplaceText(0x0871, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Hmm... Vamos ver.|19", NULL);
EZTR_Basic_ReplaceText(0x0872, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Opa! Voce de novo?|11Se quiser jogar de novo,|11custa |0610 rupias|00.|19", NULL);
EZTR_Basic_ReplaceText(0x0873, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que vai ser?|11 |11|02|02|C2Vou jogar\n|11Nao, obrigado|BF", NULL);
EZTR_Basic_ReplaceText(0x0874, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tudo bem, entao. Voce nunca vai ser|11um adulto respeitavel se nao|11se desafiar.|BF", NULL);
EZTR_Basic_ReplaceText(0x0875, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ora, voce nao tem Rupias o bastante!|11Nao tente me enganar!|BF", NULL);
