EZTR_Basic_ReplaceText(0x0877, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Atirar numa velha patetica|11|0110 vezes|00! Queria ver a cara dos seus|11pais ouvindo isso!|BF", NULL);
EZTR_Basic_ReplaceText(0x0878, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, " acertos|11Olha so... voce e bom mesmo.|11|12Bem, como prometido...|11Aqui! Pegue isso.|19", NULL);
EZTR_Basic_ReplaceText(0x0879, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Talvez seja impossivel bater esse|11recorde.|11|12Mas se quiser tentar de novo,|11e so falar comigo!|BF", NULL);
EZTR_Basic_ReplaceText(0x087A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nossa! Que descuido!|11 acertos, hein...|19", NULL);
EZTR_Basic_ReplaceText(0x087B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por que nao volta depois de|11praticar um pouco?|BF", NULL);
EZTR_Basic_ReplaceText(0x087C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nossa. Que descuido!|11|01 acertos,|00 e isso?|11|12Voce precisa fazer mais que |01 acertos|00.|11Caso contrario, sem premio.|19", NULL);
EZTR_Basic_ReplaceText(0x087D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "!|11Muito bom, considerando...|11|12Bem, como prometido...|11Aqui! Pegue isso.|19", NULL);
