EZTR_Basic_ReplaceText(0x0886, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ha muito tempo, esse meu nariz potente|11conseguia detectar eles onde quer que|11crescessem...|19", NULL);
EZTR_Basic_ReplaceText(0x0887, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas ultimamente meu nariz perdeu|11o jeito...|11|12Envelhecer e dificil...|19", NULL);
EZTR_Basic_ReplaceText(0x0888, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mmm...|11Esse cogumelo tambem tem um cheiro bom.|19", NULL);
EZTR_Basic_ReplaceText(0x0889, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pago uma fortuna por ele.|11Voce tem que me vender!|11Aqui!|19", NULL);
EZTR_Basic_ReplaceText(0x088A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Continue trazendo mais!|19", NULL);
