EZTR_Basic_ReplaceText(0x0E47, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estou perturbado tambem...|19", NULL);
EZTR_Basic_ReplaceText(0x0E48, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O Anciao foi para Snowhead e nao voltou, entao seu filho nao para de chorar.|19", NULL);
EZTR_Basic_ReplaceText(0x0E49, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce nao encontrar o Anciao Goron e pedir que volte... Nunca conseguirei dormir.|19", NULL);
