EZTR_Basic_ReplaceText(0x0E80, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|17Eu odeio!|18 |17Eu odeio!|18|11|17Quero ver!|18|11|17Quero ver!|18|11Quero ver a corrida!|BF", NULL);
EZTR_Basic_ReplaceText(0x0E81, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|17Quebre!|18 |17Quebre!|18|11|17Quero ir pra corrida!|18|11Quero ir pra corrida!|BF", NULL);
EZTR_Basic_ReplaceText(0x0E82, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Veio brincar?|BF", NULL);
EZTR_Basic_ReplaceText(0x0E83, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se puder, va ver as Corridas Goron que vao acontecer do outro lado desta montanha.|BF", NULL);
EZTR_Basic_ReplaceText(0x0E84, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso, Darmi!|11Foi incriiiivel!|11|12Vamos! Se nao nos apressarmos, a corrida vai comecar. Vamos! Rapido!|BF", NULL);
EZTR_Basic_ReplaceText(0x0E85, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "As Corridas Goron que celebram a primavera estao prestes a comecar.|BF", NULL);
