EZTR_Basic_ReplaceText(0x0FB6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "......|11Nada. Ta usando o instrumento|11errado?|BF", NULL);  
EZTR_Basic_ReplaceText(0x0FB7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso! Esse e o instrumento!|BF", NULL);  
EZTR_Basic_ReplaceText(0x0FB8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hmm...|11Se esses Zoras nasceram pra|11ensinar essa musica, toque ela|11pro Zora que botou os ovos!|BF", NULL);  
EZTR_Basic_ReplaceText(0x0FB9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu cuido dos filhotes. Va achar o|01Zora que botou esses ovos|00! Rápido!|19", NULL);  
EZTR_Basic_ReplaceText(0x0FBA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Isso e muito estranho.|11|12Se filhotes Zora ensinam musicas,|11eles ainda tem muitos misterios.|19", NULL);  
EZTR_Basic_ReplaceText(0x0FBB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que foi aquilo?|11Você sabe de algo, ne?|19", NULL);  
EZTR_Basic_ReplaceText(0x0FBC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao entendo, mas o oceano|11voltou ao normal. Isso tem a ver|11com a musica, ne? Você sabe.|BF", NULL);  
EZTR_Basic_ReplaceText(0x0FBD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O mar esfriou. Veio nadar?|11|12Se afogar com esse corpao,|11problema seu!|19", NULL);  
EZTR_Basic_ReplaceText(0x0FBE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O mar esfriou. Veio nadar?|11|12Com esse corpinho, vai se afogar!|19", NULL);  
