EZTR_Basic_ReplaceText(0x12E8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mikau, voce viu algum|11|01peixe dourado |00por aqui?|19", NULL);
EZTR_Basic_ReplaceText(0x12E9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|01Peixes dourados|00 conhecem bem|11essa area.|11|12Eu estava pensando em pegar um|11para me guiar ate o |01Pinnacle Rock|00...|19", NULL);
EZTR_Basic_ReplaceText(0x12EA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se a agua nao estivesse tao turva,|11eu nao precisaria de orientacao|11de um |01peixe dourado|00.|19", NULL);
EZTR_Basic_ReplaceText(0x12EB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ouvi dizer que os piratas foram|11atacados por cobras marinhas perto|11do covil das criaturas.|11|12Parece que deixaram cair algo|11|01valioso|00 la. Voce nao fica curioso|11sobre o que era, Mikau?|11|12Mas teriamos que atravessar essa|11agua turva para procurar...|11|12Onde estao os |01peixes dourados|11|00quando precisamos deles?|19", NULL);
EZTR_Basic_ReplaceText(0x12EC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Yo, Mikau!|11A agua do mar esta voltando|11ao normal aos poucos.|19", NULL);


EZTR_Basic_ReplaceText(0x12ED, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas aquela agua estranha e turva ainda|11nao sumiu completamente...|19", NULL);
EZTR_Basic_ReplaceText(0x12EE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Logo logo, os peixes vao voltar|11tambem!|19", NULL);
EZTR_Basic_ReplaceText(0x12EF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce esta tomando um banho de mar|11relaxante? Essa agua nao esta|11quente demais pra ser agradavel?|19", NULL);
EZTR_Basic_ReplaceText(0x12F0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E com toda essa agua turva por ai,|11e melhor tomar cuidado!|19", NULL);
EZTR_Basic_ReplaceText(0x12F1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce nao pode dar um bom mergulho|11agora que a temperatura da agua|11baixou?|19", NULL);
EZTR_Basic_ReplaceText(0x12F2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E ai?|19", NULL);
EZTR_Basic_ReplaceText(0x12F3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! Mikau!|11O que voce esta fazendo num lugar|11como esse?|19", NULL);
EZTR_Basic_ReplaceText(0x12F4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa e a sombria |01Fortaleza dos|11Piratas|00. Nao acho que voce deva|11chegar muito perto.|19", NULL);
EZTR_Basic_ReplaceText(0x12F5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Uh... Mas eu estou bem...|19", NULL);
EZTR_Basic_ReplaceText(0x12F6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bem, na verdade...|11|12Os piratas dessa fortaleza sao|11todas mulheres. E melhor ainda, ouvi|11dizer que sao lindas.|19", NULL);
EZTR_Basic_ReplaceText(0x12F7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Heh, heh... Entao eu pensei que|11talvez devesse dar uma olhada.|11|12O que??|11Nao me olhe assim...|19", NULL);
EZTR_Basic_ReplaceText(0x12F8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A Fortaleza dos Piratas geralmente|11fica trancada por um portao de ferro,|11entao voce nao consegue entrar por aqui.|19", NULL);
EZTR_Basic_ReplaceText(0x12F9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E mesmo que voce entrasse, nao e|11como se os piratas fossem te|11receber bem.|19", NULL);
EZTR_Basic_ReplaceText(0x12FA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Yo, Mikau!|11Voce fez algo com os piratas?|19", NULL);
EZTR_Basic_ReplaceText(0x12FB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Os piratas estavam procurando|11por um Zora vestido com|02 roupas verdes|00.|19", NULL);
EZTR_Basic_ReplaceText(0x12FC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao seria voce?|19", NULL);
EZTR_Basic_ReplaceText(0x12FD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Parece que os piratas tinham|11algo pendente pra resolver com voce...|19", NULL);
EZTR_Basic_ReplaceText(0x12FE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce fez alguma coisa?|19", NULL);
EZTR_Basic_ReplaceText(0x12FF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa e sua primeira vez no oceano?|11Essa e a sombria|11Fortaleza dos Piratas.|19", NULL);
EZTR_Basic_ReplaceText(0x1300, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce ficar por aqui por muito tempo,|11os piratas vao te ver e te pegar.|19", NULL);
EZTR_Basic_ReplaceText(0x1301, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce veio aqui pra nadar,|11melhor ir pra outro lugar.|19", NULL);


EZTR_Basic_ReplaceText(0x1302, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mikau! O que voce esta fazendo?|11Todo mundo ja esta no palco.|19", NULL);
EZTR_Basic_ReplaceText(0x1303, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Os Indigo-Go's vao comecar|11o ensaio em breve.|19", NULL);
EZTR_Basic_ReplaceText(0x1304, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mikau! Cara, seu jeito de tocar|11guitarra e o melhor!|19", NULL);
EZTR_Basic_ReplaceText(0x1305, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que achou dos Indigo-Go's?|11Eles nao sao os melhores?|19", NULL);
EZTR_Basic_ReplaceText(0x1306, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Como se sente, Mikau? Nao vemos|11a hora de te ouvir!|19", NULL);
EZTR_Basic_ReplaceText(0x1307, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estou tao animado...|19", NULL);
EZTR_Basic_ReplaceText(0x1308, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Yeah! Mikau, a voz da Lulu nao|11e incrivel?|19", NULL);
EZTR_Basic_ReplaceText(0x1309, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei! Voce ouviu aquilo? Isso|11garante que o show na cidade|11vai ser um sucesso.|19", NULL);
EZTR_Basic_ReplaceText(0x130A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Atrasado, Mikau?|11Corre pro palco.|19", NULL);
EZTR_Basic_ReplaceText(0x130B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Shhh!|11O ensaio deles vai comecar.|19", NULL);
EZTR_Basic_ReplaceText(0x130C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mikau!|11Essa musica nova tem uma vibe|11legal. Eu gostei mesmo.|19", NULL);
EZTR_Basic_ReplaceText(0x130D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que voce acha?|11Essa nova musica dos Indigo-Go's|11nao ta otima?|19", NULL);
EZTR_Basic_ReplaceText(0x130E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mikau!!!|11Corre... Faz sua guitarra chorar|11por mim!|19", NULL);
EZTR_Basic_ReplaceText(0x130F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao assista ao ensaio daqui.|19", NULL);
EZTR_Basic_ReplaceText(0x1310, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ohh!|11Voce arrasa! Seu jeito de tocar|11guitarra e mesmo o melhor!|19", NULL);
EZTR_Basic_ReplaceText(0x1311, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eles nao sao incriveis?|11O show na cidade... Vai ser|11ainda melhor.|19", NULL);
EZTR_Basic_ReplaceText(0x1312, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mikau! Mal posso esperar pra ouvir|11a nova musica!|19", NULL);
EZTR_Basic_ReplaceText(0x1313, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, voce tem sorte! Acabei de|11ouvir que eles vao tocar uma|11musica nova no ensaio.|19", NULL);
EZTR_Basic_ReplaceText(0x1314, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa musica e otima!|11Mas ela parecia um pouco diferente|11das musicas do Evan.|19", NULL);
EZTR_Basic_ReplaceText(0x1315, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce ouviu a musica nova?|11Acho que vai agradar na cidade|11tambem.|19", NULL);
EZTR_Basic_ReplaceText(0x1316, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei! Ei, Mikau!|11Nao fique por aqui.|11Corre e comeca o ensaio!|19", NULL);


EZTR_Basic_ReplaceText(0x1317, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Acho que os Indigo-Go's vao comecar|11o ensaio em breve. O que o Mikau|11anda fazendo?|19", NULL);
EZTR_Basic_ReplaceText(0x1318, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso nao foi legal, Mikau. Nao se atrase|11pros ensaios. Mas foi uma boa|11apresentacao.|19", NULL);
EZTR_Basic_ReplaceText(0x1319, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que achou?|11Mal pode esperar pelo show, ne?|19", NULL);
EZTR_Basic_ReplaceText(0x131A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce finalmente veio, Mikau. Os outros|11membros estao prontos!|19", NULL);
EZTR_Basic_ReplaceText(0x131B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A lua tem estado meio assustadora|11por aqui ultimamente. Voce percebeu?|11Sera que so eu acho isso?|19", NULL);
EZTR_Basic_ReplaceText(0x131C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso teve uma boa sensacao.|11Se o show for assim...|12Mas claro que vai ser.|11Desculpa. Nao ligue pra mim.|19", NULL);
EZTR_Basic_ReplaceText(0x131D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa foi uma apresentacao perfeita|11dos Indigo-Go's, nao foi? Mas|11tenho um pressentimento ruim|11sobre algo...|19", NULL);
EZTR_Basic_ReplaceText(0x1388, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa!|11Deeeixa!|19", NULL);
EZTR_Basic_ReplaceText(0x1389, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce nao tem isso, eu nao tenho|11uso pra voce! Va emboraaa!|BF", NULL);
EZTR_Basic_ReplaceText(0x138A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! Iiisso! Iiiisso! Eu nao sinto|11nenhuma pena de voce!|BF", NULL);
EZTR_Basic_ReplaceText(0x138B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Nao e o bastante.|11Deeeixa mais!|BF", NULL);
EZTR_Basic_ReplaceText(0x138C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa algo azul que|11traga saude!|19", NULL);
EZTR_Basic_ReplaceText(0x138D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa algo delicioso pra eu|11mastigar. Algo que brota|11quando e regado.|11De preferencia cinco deles...|19", NULL);
EZTR_Basic_ReplaceText(0x138E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa H...2...O.|19", NULL);
EZTR_Basic_ReplaceText(0x138F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa algo deliciosamente|11fresco!|19", NULL);
EZTR_Basic_ReplaceText(0x1390, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa algo pequeno e|11assustador!|19", NULL);
EZTR_Basic_ReplaceText(0x1391, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa algo que|11faça um clarão ofuscante!|11De preferencia dez deles.|19", NULL);
EZTR_Basic_ReplaceText(0x1392, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa dez explosoes|11refrescantes!|19", NULL);
EZTR_Basic_ReplaceText(0x1393, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa algo quente que|11derreta gelo e acalme o|11espirito.|19", NULL);
EZTR_Basic_ReplaceText(0x1394, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeixa um fantasma... Um bem|11grande!|19", NULL);
EZTR_Basic_ReplaceText(0x1395, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deeeixa algo rico em|11calcio!|19", NULL);

EZTR_Basic_ReplaceText(0x1396, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mestre! Voce chamou!|19", NULL);
EZTR_Basic_ReplaceText(0x1397, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...!!!|11|12|17O que voce e???|18|19", NULL);
EZTR_Basic_ReplaceText(0x1398, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Lamento...|11Embora rival, voce foi|11espetacular.|11|12Farei minha despedida abrindo|11meu coracao e revelando minha sabedoria...|19", NULL);
EZTR_Basic_ReplaceText(0x1399, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Crer ou nao crer e com voce.|11|12Morrer sem deixar um corpo...|11Esse e o caminho de nos Garo.|19", NULL);
EZTR_Basic_ReplaceText(0x139A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Para cruzar o vale de Ikana, aponte|11para as bestas do rio com a|11ponta de flecha que|01 congela|00.|19", NULL);
EZTR_Basic_ReplaceText(0x139B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A alma do compositor chamado|11Flat repousa no Cemiterio Ikana.|11Ouvi que seu irmao, Sharp, esta|11aqui em Ikana.|19", NULL);
EZTR_Basic_ReplaceText(0x139C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que foi obtido no Castelo Ikana|11abrira o caminho para a|11|01Stone Tower|00. So sei disso.|19", NULL);
EZTR_Basic_ReplaceText(0x139D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "No topo da colina em Ikana, nao ha|11sinal de humanos, exceto pelo|01|pai e filho|00 que vivem na casa|11com a roda d'agua.|19", NULL);
EZTR_Basic_ReplaceText(0x139E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A cada|01 dois minutos|00 em |01todos os dias|00,|11a |01menina|00 da casa de musica vai ao poco|11seco verificar algo.|10Mas enquanto os espiritos vagam|11fora de sua casa, ela nao ousa sair.|19", NULL);
EZTR_Basic_ReplaceText(0x139F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Para reviver o rio seco da colina|11Ikana, va ate a |01caverna da fonte d'agua|00.|19", NULL);
EZTR_Basic_ReplaceText(0x13A0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se alguem entrar na caverna da|11fonte sem conhecer a musica|11enterrada em um tumulo, esse|11visitante encontrara o desastre.|19", NULL);
EZTR_Basic_ReplaceText(0x13A1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Para salvar o humano amaldicoado,|11sua alma deve ser |01curada|00.|19", NULL);
EZTR_Basic_ReplaceText(0x13A2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O poco no topo da |01colina|00 e o poco|11do |01jardim interno|00 do Castelo Ikana sao|11o mesmo.|19", NULL);
EZTR_Basic_ReplaceText(0x13A3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Como os Gibdos no poco de Ikana|11tem arrependimentos e desejam|01itens|11|00deste mundo, continuam a vagar.|19", NULL);
EZTR_Basic_ReplaceText(0x13A4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A maioria do que os Gibdos|11|01arrependem|00 esta |01dentro |00do|11proprio poco.|19", NULL);
EZTR_Basic_ReplaceText(0x13A5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Os ReDeads em Ikana eram membros|11do |01grupo de danca|00 do castelo...|19", NULL);
EZTR_Basic_ReplaceText(0x13A6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Um buraco pode ser aberto no|11teto de uma sala no Castelo Ikana.|11|12Mas nao pode ser quebrado sem|11um explosivo poderoso.|19", NULL);
EZTR_Basic_ReplaceText(0x13A7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Para entrar no Castelo Ikana, ha|11uma |01rota secreta|00 alem da entrada|11do poco.|19", NULL);
EZTR_Basic_ReplaceText(0x13A8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Para conter a furia do Rei do|11Castelo Ikana, |01queime|00 o que bloqueia|11a luz e brilhe os |01raios sagrados|00.|19", NULL);
EZTR_Basic_ReplaceText(0x13AE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pensar que fui derrotado...|11Embora rival, voce foi|11espetacular.|11|12Farei minha despedida abrindo|11meu coracao e revelando minha sabedoria...|19", NULL);
EZTR_Basic_ReplaceText(0x13AF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se atirar a luz sagrada dourada|11no |01emblema vermelho|00 manchado de|11sangue fora do templo...|10as coisas se reorganizarao: a terra|11nascera nos ceus e a lua na terra.|19", NULL);
EZTR_Basic_ReplaceText(0x13B0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao esqueca estas palavras...|11Morrerei sem deixar um corpo.|19", NULL);
EZTR_Basic_ReplaceText(0x13B1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa e a lei de nos Garo.|BF", NULL);
EZTR_Basic_ReplaceText(0x13B2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Tragaaaam-nos!|19", NULL);
EZTR_Basic_ReplaceText(0x13B3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aquelesss...Nossos amigoss...|11Tragaaaam-nos!|BF", NULL);
EZTR_Basic_ReplaceText(0x13EC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|17Hein?|18|19", NULL);
EZTR_Basic_ReplaceText(0x13ED, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aah! Capitao, senhor!!!|11Com licenca, senhor!|11|12Todos, atencao para o capitao!|19", NULL);
EZTR_Basic_ReplaceText(0x13EE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Faz tempo que nao o vemos, capitao!|11|12Como ordenado, guardamos esses|11tumbas com rigor.|19", NULL);
EZTR_Basic_ReplaceText(0x13EF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estavamos todos aguardando suas|11proximas ordens, senhor.|19", NULL);
EZTR_Basic_ReplaceText(0x13F0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que faremos?|11 |11|02|02|C2Guardar o tumulo\n|11Abrir o tumulo|BF", NULL);
EZTR_Basic_ReplaceText(0x13F1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sim, senhor! Continuaremos com|11esta estrategia!|19", NULL);
EZTR_Basic_ReplaceText(0x13F2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|17Sim, senhor!|18|19", NULL);
EZTR_Basic_ReplaceText(0x13F3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A-abrir?|19", NULL);
EZTR_Basic_ReplaceText(0x13F4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Todos!|11Sigam-me!|19", NULL);
EZTR_Basic_ReplaceText(0x13F5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Capitao!|11Qual e o proximo comando?|19", NULL);
EZTR_Basic_ReplaceText(0x13F6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hein?|19", NULL);
EZTR_Basic_ReplaceText(0x13F7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Capitao!|11D-desculpe, senhor!|BF", NULL);
EZTR_Basic_ReplaceText(0x13F8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O lider do esquadrao esta na frente|11daquele tumulo ali, senhor.|BF", NULL);
EZTR_Basic_ReplaceText(0x13F9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A melodia que invoca as lagrimas|11dos anjos repousa aqui.|BF", NULL);
EZTR_Basic_ReplaceText(0x13FA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Um receptaculo que guarda espiritos|11vagantes repousa aqui.|BF", NULL);
EZTR_Basic_ReplaceText(0x13FB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Uma peca que cura a alma ferida|11repousa aqui.|11|12Quando alguem com olhos que veem|11a verdade chegar, a peca abaixo|11despertara.|BF", NULL);
EZTR_Basic_ReplaceText(0x13FC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce que me |01despertou|00, lute comigo.|11Entao apagarei a chama furiosa.|BF", NULL);
EZTR_Basic_ReplaceText(0x13FD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aaaaieeee!!!|11E-eles estao soltos!|11|12Por que estao fora antes da noite?|BF", NULL);
EZTR_Basic_ReplaceText(0x13FE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu sou Dampe, o guardiao do|11cemiterio.|11|12Meu rosto assusta, mas nao sou|11uma pessoa ruim!|BF", NULL);
EZTR_Basic_ReplaceText(0x13FF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Todos os tumulos aqui sao da familia|11do Rei do Castelo Ikana, alem das|11montanhas.|10Ate hoje, os |01fantasmas|00 saem|11a noite. E um cemiterio assustador.|BF", NULL);
EZTR_Basic_ReplaceText(0x1400, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Viu o enorme esqueleto no fundo|11deste cemiterio?|11|12Meu pai dizia que eram os restos|11do antigo Soldado Real que|11guardava este cemiterio.|10Mesmo morto, seus restos bloqueiam|11o caminho. Ele ainda protege o|11|01tesouro da Familia Real|00.|10Ele deve ter sido um grande soldado.|BF", NULL);
EZTR_Basic_ReplaceText(0x1401, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Quer ver os ossos dançantes?|11|12Se sim, espere aqui ate a |01noite|00.|11|12Mas eu nao quero ver algo tao|11maligno...|BF", NULL);
EZTR_Basic_ReplaceText(0x1402, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao me incomode!|11|12Logo, muitos fantasmas assustadores|11aparecerao.|11|12Va para casa tambem...|11Antes de ser atacado!|BF", NULL);
EZTR_Basic_ReplaceText(0x1403, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ha muitos morcegos hoje.|11Nao gosto deles.|11|12Queria que fossem embora.|BF", NULL);
EZTR_Basic_ReplaceText(0x1404, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aaaieeee!!!|11E-eles estao soltos!|11|12Saiam!|BF", NULL);
EZTR_Basic_ReplaceText(0x1405, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce? Quem e? Nao vejo bem...|11Voce nao e um fantasma...e?|BF", NULL);

EZTR_Basic_ReplaceText(0x1406, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Uma fada?|11|12Oh, e a luz de uma fada. Perfeito.|11|12Vim buscar o |01tesouro lendario|00 da|11|01Familia Real|00, mas minha tocha se apagou.|11|12Poderia andar na frente e |01iluminar o caminho|00?|BF", NULL);
EZTR_Basic_ReplaceText(0x1407, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor?|11 |11|02|02|C2Sim\n|11Nao|BF", NULL);
EZTR_Basic_ReplaceText(0x1408, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao desistirei. Vou insistir ate voce|11aceitar.|11|12Foi assim que conquistei minha esposa.|11|12Entao...Me guiara pela escuridao?|BF", NULL);
EZTR_Basic_ReplaceText(0x1409, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aceita?|11Usarei sua luz enquanto ando.|11|12Me leve ate onde acha que o|11tesouro esta enterrado.|BF", NULL);
EZTR_Basic_ReplaceText(0x140A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Dividirei o tesouro com voce...|11Conto com voce.|BF", NULL);
EZTR_Basic_ReplaceText(0x140B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Onde estava? Sumiu, e sua luz e|11minha unica esperanca.|BF", NULL);
EZTR_Basic_ReplaceText(0x140C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei! Para onde foi?|11Ande mais devagar.|BF", NULL);
EZTR_Basic_ReplaceText(0x140D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh!|11Ha algo estranho aqui.|11|12Quer que eu cave?|11|02 |11|02|C2Sim\n|11Nao|BF", NULL);
EZTR_Basic_ReplaceText(0x140E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Entao me leve a outro lugar.|BF", NULL);
EZTR_Basic_ReplaceText(0x140F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nada encontrado.|11Me leve a outro lugar.|BF", NULL);
EZTR_Basic_ReplaceText(0x1410, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ha algo estranho, mas nao e o|01tesouro|00. Mostre outro lugar.|BF", NULL);
EZTR_Basic_ReplaceText(0x1411, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Waah!!!|11E o |01lider|00 dos fantasmas!|BF", NULL);
EZTR_Basic_ReplaceText(0x1412, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A alma de um bravo soldado de|11Ikana repousa aqui.|BF", NULL);
EZTR_Basic_ReplaceText(0x1413, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Foi voce que espantou os morcegos?|11|12Nao e muito, mas aqui estao|11|0630 rupias|00 pelo trabalho.|11Pegue!|BF", NULL);
EZTR_Basic_ReplaceText(0x1414, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu...Nao vi nada e nao sei de nada...|BF", NULL);
EZTR_Basic_ReplaceText(0x1450, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei, que |01espada|00 legal...Heh, heh...|11|11Ultimamente, |01fantasmas|00 assustadores|11aparecem em bandos na |01Vila Ikana|00.|10Dizem ser fantasmas da |01Familia Real|11de Ikana|00.|11|11Ninguem mora la, entao me mudei para|11perto. Heh, heh...|11|12So ha um |01pai e filho|00 curiosos|11estudando fantasmas...E que espada|11incrivel!|19", NULL);
EZTR_Basic_ReplaceText(0x1451, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Posso ve-la?|11 |11|02|02|C2Sim\n|11Nao|BF", NULL);
EZTR_Basic_ReplaceText(0x1452, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, tudo bem!|19", NULL);
EZTR_Basic_ReplaceText(0x1453, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hein?!? Mesmo?|11Nao quero incomodar, mas...|19", NULL);
EZTR_Basic_ReplaceText(0x1454, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que? U-uma coisa vermelha?!?|11O que e? Parece hostil!|19", NULL);
EZTR_Basic_ReplaceText(0x1455, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que? U-uma coisa vermelha?!?|11O que e? Parece hostil!|19", NULL);
EZTR_Basic_ReplaceText(0x1456, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O |01pai e filho|00 em |01Vila Ikana|00|11afugentaram os espiritos com um|11|01grande caixa de musica|00.|19", NULL);
EZTR_Basic_ReplaceText(0x1457, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas nao posso pagar por algo|11tao gigante...|19", NULL);
EZTR_Basic_ReplaceText(0x1458, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas isso sou eu...Heh, heh.|19", NULL);
EZTR_Basic_ReplaceText(0x1459, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eles precisam da |01correnteza|00 do rio|11para mover a |01caixa de musica|00.|19", NULL);
EZTR_Basic_ReplaceText(0x145A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O rio secou, entao nao ha valor em|11roubar a caixa ou saquear o lugar...|19", NULL);
EZTR_Basic_ReplaceText(0x145B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Uh...So divagando...Heh, heh.|19", NULL);
EZTR_Basic_ReplaceText(0x145C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "......|BF", NULL);
EZTR_Basic_ReplaceText(0x145D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Encontrei ele, |02garoto de chapeu verde|00...|19", NULL);
EZTR_Basic_ReplaceText(0x145E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ele usa este lugar para guardar|11|01itens roubados|00. Seu nome e |01Sakon|00.|11|12Segui-o ate aqui.|19", NULL);
EZTR_Basic_ReplaceText(0x145F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Seu |01estoque|00 esta atras desta|11|01porta de pedra|00.|11|12So |01Sakon|00 pode abri-la. Precisamos|11esperar ele chegar.|19", NULL);
EZTR_Basic_ReplaceText(0x1460, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Esperarei...Prometi a Anju.|11Ele aparecera.|BF", NULL);
EZTR_Basic_ReplaceText(0x1461, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Ah!|BF", NULL);
EZTR_Basic_ReplaceText(0x1462, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Veja!|11Ha uma |01mascara|05 ali!!!|BF", NULL);
EZTR_Basic_ReplaceText(0x1463, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E a Mascara do Sol!|BF", NULL);
EZTR_Basic_ReplaceText(0x1464, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora ferrei tudo!|BF", NULL);
EZTR_Basic_ReplaceText(0x1465, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|01Pise|00 naquele |01interruptor|00!!!|BF", NULL);
EZTR_Basic_ReplaceText(0x1466, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O que??|11Esta dando ordens?!?|BF", NULL);
EZTR_Basic_ReplaceText(0x1467, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A porta so fica aberta enquanto o|01interruptor|00 esta |01pressionado|00!|BF", NULL);
EZTR_Basic_ReplaceText(0x1468, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Deve haver um mecanismo nesta sala|11que abre a porta! Ohhh! A mascara!|BF", NULL);
EZTR_Basic_ReplaceText(0x1469, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ele esta tentando fugir com ela...|11Precisamos nos apressar!|BF", NULL);
EZTR_Basic_ReplaceText(0x146A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso nao adianta. Nao e o interruptor...|11|12Verifique a outra sala. Deve haver|11um mecanismo. Rápido!!!|BF", NULL);
EZTR_Basic_ReplaceText(0x146B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Nao gosto dele...|11Mas temos escolha?|11Ajuda-lo?|11|12Nao agir em perigo quando necessario|11e coisa de |01Tael|05.|11...Vamos!|BF", NULL);
EZTR_Basic_ReplaceText(0x146C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isso! Meu sistema de seguranca e|11inquebravel!|BF", NULL);
EZTR_Basic_ReplaceText(0x146D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Estamos presos.|BF", NULL);
EZTR_Basic_ReplaceText(0x146E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sinto que voce se envolveu nisso.|11Se puder sair, va.|11|12Anju ja fugiu para o rancho da Cremia.|BF", NULL);
EZTR_Basic_ReplaceText(0x146F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Voce fez o possivel.|11Ela...entendera.|10Toque sua ocarina para sairmos.|11Deixe-o aqui.|BF", NULL);
EZTR_Basic_ReplaceText(0x1470, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Recuperei a |01Mascara do Sol|00!|BF", NULL);
EZTR_Basic_ReplaceText(0x1471, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ainda ha tempo!|11Preciso voltar a cidade!|BF", NULL);
EZTR_Basic_ReplaceText(0x1472, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hein? Ainda nao?|11Nao estou me destacando?|11|12...Estranho.|11Mas estou tentando...|19", NULL);
EZTR_Basic_ReplaceText(0x1473, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hein?|11Nao me diga...Isso e...|19", NULL);

EZTR_Basic_ReplaceText(0x1474, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estou chocado. Voce e a primeira|11pessoa que ja falou comigo.|11|12Estou aqui ha muitos anos,|11acenando meus bracos e pedindo|11ajuda, mas todos me ignoram|11e passam direto.|10E porque sou tao impressionante|11quanto uma pedra, ne?...Estou|11acostumado, no entanto.|19", NULL);
EZTR_Basic_ReplaceText(0x1475, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hmm...Tenho um pedido...Pode me|11dar algum remedio que faca ate|11uma pedra insignificante como eu|11se sentir melhor?|19", NULL);
EZTR_Basic_ReplaceText(0x1476, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Afinal, sou uma pedra, entao|11como uma pedra, nao vou me mover.|11Vou esperar bem aqui.|19", NULL);
EZTR_Basic_ReplaceText(0x1477, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, aquilo...E isso?|19", NULL);
EZTR_Basic_ReplaceText(0x1478, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Acho que me sinto melhor.|19", NULL);
EZTR_Basic_ReplaceText(0x1479, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Obrigado...|11Oh...aqui...|11Em gratidao...|19", NULL);
EZTR_Basic_ReplaceText(0x147A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora...Vou praticar para me|11destacar...|19", NULL);
EZTR_Basic_ReplaceText(0x147B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao sou mais dos vivos...Minha|11tristeza para a lua...Nao deixei|11minha danca para o mundo...Estou|11cheio de arrependimento.|10|17(Translation) |11Estou decepcionado, oh lua.|11Eu morri!|18|11|12|17Oh, eu planejava unir o mundo|11e mistura-lo em um grande caldeirao|11com minha danca!|18|11|12|17Se ao menos eu tivesse ensinado minha|11nova danca a alguem...|18|19", NULL);
EZTR_Basic_ReplaceText(0x147C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Espalhem minha danca pelo mundo...|11Treinem seus seguidores...|11|12|17(Translation) |11Eu a ensinei a voce, agora faca|11dela uma moda de danca popular!|18|19", NULL);
EZTR_Basic_ReplaceText(0x147D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Estou contando com voce.|11|12|17(Translation) |11Estou contando com voce.|18|19", NULL);
EZTR_Basic_ReplaceText(0x14B4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce e quem libertou minha|11alma?|BF", NULL);
EZTR_Basic_ReplaceText(0x14B5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Servi a familia real de Ikana.|11Sou o compositor chamado |01Flat|00.|BF", NULL);
EZTR_Basic_ReplaceText(0x14B6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "As musicas ligadas a Familia Real|11que restam aqui foram todas|11compostas por meu irmao e eu.|BF", NULL);
EZTR_Basic_ReplaceText(0x14B7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh...Sharp,|11meu querido irmao.|BF", NULL);
EZTR_Basic_ReplaceText(0x14B8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ele vendeu sua alma ao diabo e|11foi quem me prendeu aqui...|BF", NULL);
EZTR_Basic_ReplaceText(0x14B9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce que nao teme os mortos,|11aprenda bem a musica inscrita|11atras de mim...|BF", NULL);
EZTR_Basic_ReplaceText(0x14BA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E se encontrar meu irmao,|11gostaria que o informasse...|BF", NULL);
EZTR_Basic_ReplaceText(0x14BB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Os mil anos de gotas de chuva|11convocadas por minha musica sao|11minhas lagrimas.|11|12O trovao que atinge a terra|11e minha raiva!|BF", NULL);
EZTR_Basic_ReplaceText(0x14BC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Fiz meu pedido.|BF", NULL);
EZTR_Basic_ReplaceText(0x14BD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Os mil anos de gotas de chuva|11convocadas por minha musica sao|11minhas lagrimas.|11|12O trovao que atinge a terra|11e minha raiva!|BF", NULL);
EZTR_Basic_ReplaceText(0x14BE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aqui esta escrita a musica que|11purificara sua alma amaldicoada|11e negra.|BF", NULL);
EZTR_Basic_ReplaceText(0x14BF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Que negocios voce tem no Reino|11Ikana, terra onde so os mortos|11vagam?|BF", NULL);
EZTR_Basic_ReplaceText(0x14C0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Este nao e lugar para alguem tao|11cheio de vida como voce.|BF", NULL);
EZTR_Basic_ReplaceText(0x14C1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ou voce diz que deseja se juntar|11aos mortos?|11|12Isso e aceitavel...|BF", NULL);
EZTR_Basic_ReplaceText(0x14C2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se for o caso, entao durma|11suavemente ao som da melodia das|11trevas que o grande compositor,|11Sharp, tocara...|10e junte-se aos mortos.|BF", NULL);
EZTR_Basic_ReplaceText(0x14C3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entendo seu desejo...|11|12Voce nao desiste. Vejo que|11realmente deseja se juntar aos|11mortos.|BF", NULL);
EZTR_Basic_ReplaceText(0x14C4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hmm?|11De algum modo, meu coracao se|11acalmou. Esta melodia tem uma|11serenidade... E ainda...|BF", NULL);
EZTR_Basic_ReplaceText(0x14C5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Para um das trevas e mortos, como|11eu, uma musica assim nao tem mais|11significado.|11|12Voce deve acabar com sua|11resistencia inutil e rapidamente|11se juntar aos mortos.|BF", NULL);
EZTR_Basic_ReplaceText(0x14C6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O-Que e isso?|11...Esta musica?|BF", NULL);
EZTR_Basic_ReplaceText(0x14C7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...N-Nao, nao pode ser. |11Esta musica...|BF", NULL);
EZTR_Basic_ReplaceText(0x14C8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Flat, meu querido irmao.|11|12Perdoe seu irmao tolo que sonhou|11com o revival da Familia Real...|BF", NULL);
EZTR_Basic_ReplaceText(0x14C9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Voce que nao teme os mortos...|BF", NULL);
EZTR_Basic_ReplaceText(0x14CA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Com a musica de meu irmao, voce|11quebrou a maldicao que pesava|11sobre mim. Tudo gracas a voce.|BF", NULL);
EZTR_Basic_ReplaceText(0x14CB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nos, mortos, nao deveriamos|11permanecer nesta terra.|11|12Foi tudo um truque daquele mascarado|11que perturbou as coisas.|BF", NULL);
EZTR_Basic_ReplaceText(0x14CC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce realmente nao teme os|11mortos...|11|12Desejo que va ao |01templo|00 nesta|11terra e corte a raiz da maldicao|11que nos atormenta.|BF", NULL);
EZTR_Basic_ReplaceText(0x14CD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Para isso...|BF", NULL);
EZTR_Basic_ReplaceText(0x14CE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu, o unico que sabe o caminho|11para o |01templo|00, direcionarei|11voce ao |01King|00.|11|12O Rei esta nas ruinas do Castelo|11Ikana, aguardando a chegada daquele|11que quebrara a maldicao.|BF", NULL);
EZTR_Basic_ReplaceText(0x14CF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Fiz meu pedido final.|BF", NULL);
EZTR_Basic_ReplaceText(0x14D0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Iii-hee-hee...|11O Reino Ikana foi fundado nesta|11terra, manchada por uma historia|11sombria, encharcada de sangue...|10Ate agora e um lugar onde espiritos|11atormentados e arrependidos se|11reunem.|19", NULL);
EZTR_Basic_ReplaceText(0x14D1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se procura alguem |01mais forte|00|11que voce, pode encontrar forca|11aqui...|11|12de um grupo de espiritos atormentados|11por arrependimentos persistentes.|19", NULL);
EZTR_Basic_ReplaceText(0x14D2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se confia em suas habilidades|11e forca...|11|12entao tente salvar estes espiritos|11errantes. |11Iii-hee-hee...|19", NULL);
EZTR_Basic_ReplaceText(0x14D3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E impossivel em seu estado atual,|11mas uma vez que aliviar seu cansaço|11e ganhar confianca em suas|11habilidades...|10Deve tentar salvar estes espiritos|11errantes.|11Iii-hee-hee...|19", NULL);
EZTR_Basic_ReplaceText(0x14D4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas o preco terreal que deve pagar|11e |0630 rupias|00!|19", NULL);
EZTR_Basic_ReplaceText(0x14D5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Fara mesmo assim?|11 |11|02|02|C2Vou fazer\n|11Nao vou fazer|BF", NULL);
EZTR_Basic_ReplaceText(0x14D6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Este e o tipo de mundo em que|11estamos, entao este e o tipo de|11negocio que devemos fazer.|11Iii-hee-hee!|19", NULL);
EZTR_Basic_ReplaceText(0x14D7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, mas nao tem |06Rupias|00|11suficientes. Bem, isso e uma pena.|19", NULL);
EZTR_Basic_ReplaceText(0x14D8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce e um garoto cheio de vigor.|11|12Derrote as damas no limite de tempo|11e descanse suas almas em paz.|19", NULL);
EZTR_Basic_ReplaceText(0x14D9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas se sua energia vital cair|11abaixo de tres coracoes, pararei|11a partida.|11|12Misericordia e o minimo que posso|11oferecer.|19", NULL);
EZTR_Basic_ReplaceText(0x14DA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Esta preparado?|11 |11|02|02|C2Sim\n|11Nao|BF", NULL);
EZTR_Basic_ReplaceText(0x14DB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Dominado pelo medo?|11Iii-hee-hee!|19", NULL);
EZTR_Basic_ReplaceText(0x14DC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Parece que suas almas foram|11curadas.|19", NULL);

EZTR_Basic_ReplaceText(0x14DD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu lhe dou o bem terreal que as|11damas guardavam. Leve-o, .|19", NULL);
EZTR_Basic_ReplaceText(0x14DE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Esse e seu nome, correto? Posso|11ler coracoes...|11|12Sabia que viria aqui...|19", NULL);
EZTR_Basic_ReplaceText(0x14DF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora, minha propria alma foi|11curada tambem. |11Com isso...|11Iii-hee-hee!|19", NULL);
EZTR_Basic_ReplaceText(0x14E0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Independente dos poderes misticos|11que possua, nao pode mais lutar.|19", NULL);
