EZTR_Basic_ReplaceText(0x1892, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, sinto muito. Já é hora de|11fechar a loja. Volte sempre.|19", NULL);
EZTR_Basic_ReplaceText(0x1893, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por hoje é só, então corra|11e vá para casa!|19", NULL);
EZTR_Basic_ReplaceText(0x1901, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É um |00Snapper|05! Pelo jeito que essas|11coisas se movem, elas nunca expõem|11a parte fraca do corpo!|BF", NULL);
EZTR_Basic_ReplaceText(0x1902, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquilo é uma |00Mini Baba|05. Não vai atacar|11a menos que você se aproxime demais, então|11cuidado onde pisa!|BF", NULL);
EZTR_Basic_ReplaceText(0x1903, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Você encontrou uma |00Mad Jelly|05.|11Como seu corpo é tão mole, ataques normais|11não farão efeito! Encontre|11outra maneira!|BF", NULL);
EZTR_Basic_ReplaceText(0x1904, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você nem conhece a|11|00Skulltula|05? Ela é protegida|11por uma casca dura, mas sua barriga|11é mole!|BF", NULL);
