EZTR_Basic_ReplaceText(0x1906, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Chuchu Azul|05...|11Esta não tem nada dentro|11dela, então é apenas um monte de|11água.|BF", NULL);
EZTR_Basic_ReplaceText(0x1907, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Não me diga que você não conhece a|11|00Deku Baba|05! Corte-a quando|11ela estender seu corpo e Noz Deku|11ou Bastões sairão.|BF", NULL);
EZTR_Basic_ReplaceText(0x1908, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bio Deku Baba|05...|11Apenas se acalme e mire com cuidado!|11E não me culpe se um golpe|11não a eliminar!|BF", NULL);
EZTR_Basic_ReplaceText(0x1909, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Não é uma |00Deku Baba|05?|11Mas parece um pouco murcha...|11Apenas corte-a. Você deve pelo menos|11conseguir um Bastão Deku dela.|BF", NULL);
EZTR_Basic_ReplaceText(0x190A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É uma |00Dexihand|05.|11Apenas tome cuidado...|11Olha, não é minha culpa se você se aproxima|11demais e ela te agarra!|BF", NULL);
EZTR_Basic_ReplaceText(0x190B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquilo é um |00Nejiron|05.|11Não se aproxime muito.|11Cheiro... Cheiro...|11Cheira a pólvora!|BF", NULL);
EZTR_Basic_ReplaceText(0x190C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquela é uma |00Abelha Gigante|05.|11Não me pergunte!|11Você pode lutar ou correr...|11É com você.|BF", NULL);

EZTR_Basic_ReplaceText(0x190D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você não conhece o|11|00Dodongo|05? Ele se move lentamente, então|11você pode dar a volta por trás dele.|11Entendeu?|BF", NULL);
EZTR_Basic_ReplaceText(0x190E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É um |00Deep Python|05. Aproxime-se dele|11e o atordoe. Se você falhar, ele te|11pegará!|BF", NULL);
EZTR_Basic_ReplaceText(0x190F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Death Armos|05, um guarda de templo...|11Olhe aquela marca vermelha em seu|11peito! Eu sei que você já viu|11algo assim antes...|BF", NULL);
EZTR_Basic_ReplaceText(0x1910, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você não conhece os|11|00Dinofols|05? Use métodos de mira|11enquanto se defende. E |11cuidado com o bafo de fogo!|BF", NULL);
EZTR_Basic_ReplaceText(0x1911, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Não me diga que você não conhece|11o |00Fire Keese|05! Derrote-o antes|11que ele te ataque.|11Eu não quero virar churrasco!|BF", NULL);
EZTR_Basic_ReplaceText(0x1912, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você não conhece|11o |00Keese|05? Use a Mira Z quando|11ele se aproximar. Mesmo que ele voe,|11eu o seguirei por você.|BF", NULL);
EZTR_Basic_ReplaceText(0x1913, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Você conhece o |00Armos|05, certo?|11Shhhh! Não toque nele! Exploda-o|11antes que ele acorde, por favor!|BF", NULL);
EZTR_Basic_ReplaceText(0x1914, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquele é um |00Eeno|05.|11Ele é persistente!|11...E é suscetível ao calor!|BF", NULL);
EZTR_Basic_ReplaceText(0x1915, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquilo não é uma |00Libélula|05?|11Enquanto você ficar longe da|11cauda dela, não há grande perigo.|BF", NULL);
