EZTR_Basic_ReplaceText(0x1917, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Ele disse que é um |00Garo|05...|11Apenas se concentre em bloquear e|11desviar dessas espadas afiadas!|BF", NULL);
EZTR_Basic_ReplaceText(0x1918, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquele é o |00Mestre Garo|05...|11Você não pode lutar com ele como um|11Garo comum. Apenas desvie dessas|11espadas...|BF", NULL);
EZTR_Basic_ReplaceText(0x1919, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É uma |00Verruga|05.|11Assim que você se livrar das|11esferas que protegem o corpo principal,|11você pode atacar o olho.|BF", NULL);
EZTR_Basic_ReplaceText(0x191A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É |00Gomess|05. Não terá fim se você não|11conseguir afastar esses morcegos|11dele. Isso ajuda em algo?|BF", NULL);
EZTR_Basic_ReplaceText(0x191B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Rápido! Persiga-o. Mesmo que isso|11signifique jogar seu próprio corpo|11nele, faça-o parar!|BF", NULL);
EZTR_Basic_ReplaceText(0x191C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquilo é uma |00Blue Bubble|05!|11Rápido! Corra! Não deixe que ela te|11amaldiçoe! Se ela vier atrás de você, defenda-se|11para bloqueá-la!|BF", NULL);
EZTR_Basic_ReplaceText(0x191D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Use métodos de Mira Z enquanto|11se defende... O |11O que poderia ser aquilo|11em um lugar tão escuro como este?|BF", NULL);
EZTR_Basic_ReplaceText(0x191E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Apenas continue defendendo e observe seus|11movimentos. Acho que estou começando a|11ver seu ponto fraco!|BF", NULL);
EZTR_Basic_ReplaceText(0x191F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você não conhece a |11|00Skullwalltula|05?|11...Apenas não toque nela, ok?|BF", NULL);
EZTR_Basic_ReplaceText(0x1921, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Rápido! Persiga-o até ter|11sua chance! Mas se você|11chegar muito perto, pode se arrepender!|BF", NULL);
EZTR_Basic_ReplaceText(0x1922, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É uma |00Chuchu Amarela|05.|11Não há nada para se preocupar.|11Ela geralmente tem algo em seu|11estômago que é útil...|BF", NULL);
EZTR_Basic_ReplaceText(0x1923, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É um |00Takkuri|05.|11Corra! Este pássaro rouba seus itens!|11Vamos! O que você está fazendo|11parado?!|BF", NULL);
EZTR_Basic_ReplaceText(0x1924, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você não conhece a|11|00Red Bubble|05? Se ela vier até você,|11assuma a posição defensiva para|11rebatê-la... Entendeu?|BF", NULL);
