EZTR_Basic_ReplaceText(0x1926, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É um |00Hiploop|05. Desvie rapidamente|11se ele atacar você. Mas você não pode|11primeiro fazer algo com a máscara|11que ele está usando?|BF", NULL);
EZTR_Basic_ReplaceText(0x1927, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Não me diga que você não conhece|11a |00Shell Blade|05! É impossível|11vencê-la se você mirar em outra coisa|11senão seu ligamento dentro da concha.|BF", NULL);
EZTR_Basic_ReplaceText(0x1928, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Se você se aproximar agora, você será|11comido! Mire nele de longe para|11enfraquecê-lo.|BF", NULL);
EZTR_Basic_ReplaceText(0x1929, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O que você está fazendo?!?|11Não há tempo a perder! Mergulhe|11e ataque-o!|11Rápido!|BF", NULL);
