EZTR_Basic_ReplaceText(0x1934, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Pense em batalhas e armas!|11|05Quando você tinha a chance antes|11que um inimigo fosse atacar,|11você geralmente não tentava atirar nele?|BF", NULL);
EZTR_Basic_ReplaceText(0x1935, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Você conhece o |00Iron|11Knuckle|05, certo? Mantenha distância do|11ataque de machado, e procure uma|11chance para retaliar.|BF", NULL);
EZTR_Basic_ReplaceText(0x1937, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Você conhece o |00Like Like|05,|11certo? Ele come tudo o que você está|11carregando. É melhor você derrotá-lo se|11quiser suas coisas de volta.|BF", NULL);

EZTR_Basic_ReplaceText(0x1939, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você não conhece o|11|00Beamos|05? Não deixe seu feixe|11te assustar. Apenas dê um bom|11tiro nele!|BF", NULL);
