EZTR_Basic_ReplaceText(0x193B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Não me diga que você não conhece|11o |00Freezard|05! Cuidado com seu|11bafo gelado! Eu odeio o f-f-frio!|BF", NULL);
EZTR_Basic_ReplaceText(0x193C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05É um |00White Boe|05...|11Apenas se acalme e ataque-o!|11Sim, sim, sim... São muitos deles, OK?|BF", NULL);
EZTR_Basic_ReplaceText(0x1942, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Você conhece o |00Octorok|05,|11certo? Tudo o que você precisa fazer é|11desviar daquela pedra que ele cospe.|BF", NULL);
EZTR_Basic_ReplaceText(0x1944, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05O quê?! Você não conhece o|11|00Poe|05? Se você tentar usar a Mira Z,|11ele desaparece.|BF", NULL);
EZTR_Basic_ReplaceText(0x1945, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aquele é um |00Gekko|05.|11E ele está bem bravo!|11Ele é bem fraco também. Ele realmente|11não deveria estar te fazendo de tolo.|BF", NULL);
EZTR_Basic_ReplaceText(0x1946, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Você não conhece o |00Blue|11Tektite|05? Use a Mira Z para segui-lo|11enquanto ele pula!|BF", NULL);
EZTR_Basic_ReplaceText(0x1947, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Você conhece o |00Leever|05, certo?|11Ele se move muito rápido, na verdade.|11Isso não é exatamente uma boa notícia,|11é?|BF", NULL);
EZTR_Basic_ReplaceText(0x1948, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Não me diga que você não conhece|11o |00Pea Hat|05! Apenas lembre-se de que|11sua área da raiz é macia!|BF", NULL);
EZTR_Basic_ReplaceText(0x1949, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Larva de Pea Hat|05... Você não conhece|11ela? Se ela vier até você, fique|11na posição defensiva para|11rebatê-la!|BF", NULL);
