EZTR_Basic_ReplaceText(0x1F4A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05...Por que voce esta olhando assim|11pra mim? Tem algo grudado|11no meu rosto?|11|12Pode parar de encarar e apenas|11abra aquela |01porta|05 pra mim?!?|11|12Por favor!!! Vai, uma menininha|11indefesa esta pedindo...|11Entao anda logo!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F4B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Ohhhh, |01Tael|05...|11Sera que aquela crianca vai|11ficar bem sozinha?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F4C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Ei, espera por mim!|11Nao me deixa pra tras!|11|12Entao, uh...|11|01Aquilo tudo la atras|05...|11Eu... uh... me desculpo, entao...|11Entao me leva com voce!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F4D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Voce quer saber daquele|11Skull Kid que acabou de fugir, ne?|11|12Bem, por acaso eu sei uma ideia de|01onde|05 ele pode ter ido.|11|12Me leva com voce e eu te ajudo.|11Combinado?|11|12Por favor?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F4E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05|17Otimo! Entao esta|11combinado!|18|11|12Agora, serei sua parceira...|11pelo menos ate pegarmos aquele|11Skull Kid...|11|12Meu nome é |01Tatl|05.|11Entao, uh, prazer em te conhecer|11ou algo assim.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F4F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Agora que tudo esta resolvido,|11podemos parar de enrolar e seguir?|11|12Se eu descobrir algo,|11aperte [C-Cima] que eu te conto.|11Espero que voce consiga se virar|11sem minha ajuda ate la!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F50, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aww, buáá.|11Por que essa carinha triste?|11|12So pensei em me divertir um pouco|11com voce...|BF", NULL);
EZTR_Basic_ReplaceText(0x1F51, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ora, vamos...|11Voce realmente acha que pode me vencer|11do jeito que estou agora?|11Tolo!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F52, EZTR_STANDARD_TEXT_BOX_I, 15, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Na terra de Hyrule, ecoa|11uma lenda. Uma lenda querida|11pela Familia Real que fala|11sobre um garoto...|1D", NULL);
EZTR_Basic_ReplaceText(0x1F54, EZTR_STANDARD_TEXT_BOX_I, 15, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Terminadas as batalhas que travou|11atraves do tempo, ele partiu|11em uma jornada. Uma jornada secreta|11e pessoal...|1D", NULL);
EZTR_Basic_ReplaceText(0x1F55, EZTR_STANDARD_TEXT_BOX_I, 15, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Uma jornada em busca de um|11amigo querido e insubstituivel...|1D", NULL);
EZTR_Basic_ReplaceText(0x1F56, EZTR_STANDARD_TEXT_BOX_I, 15, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Um amigo com quem ele se separou|11quando finalmente cumpriu seu|11destino heroico e tomou seu lugar|11entre as lendas...|1D", NULL);
EZTR_Basic_ReplaceText(0x1F5F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Aah!|11Ele acordou!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F60, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vocês...|11Nao tinham se esquecido de mim?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F61, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ainda pensavam em mim como um|11amigo?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F62, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce...|11Voce me salvou?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F63, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu achei que eles nao queriam|11ser meus amigos...|BF", NULL);
EZTR_Basic_ReplaceText(0x1F64, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas...|11Eles nao tinham se esquecido de mim...|BF", NULL);
EZTR_Basic_ReplaceText(0x1F65, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Amigos sao legais de se ter...|11Heh, heh.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F66, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce poderia ser meu amigo tambem?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F67, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eh-hee-hee... Voce tem o mesmo|11cheiro do garoto fada que me ensinou|11aquela musica na floresta...|BF", NULL);
EZTR_Basic_ReplaceText(0x1F68, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu sei, eu sei!|11Vamos fazer algo!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F69, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh... Entao o mal deixou a mascara|11afinal...|BF", NULL);
EZTR_Basic_ReplaceText(0x1F6A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Bem, agora... Eu finalmente a recuperei.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F6B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ja que estou em meio a minha|11viagem...|11|12Preciso me despedir.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F6C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce nao deveria estar voltando|11pra casa tambem?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F6D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Sempre que ha um encontro, uma|11despedida certamente vira.|11|12No entanto, essa despedida nao|11precisa durar para sempre...|11|12Se for para sempre ou|11apenas por pouco tempo...|11Isso depende de voce.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F6E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Com isso, peco licenca...|BF", NULL);
EZTR_Basic_ReplaceText(0x1F6F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Mas, nossa, voce realmente conseguiu|11fazer muitas pessoas felizes.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F70, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "As mascaras que voce tem estao cheias|11de felicidade.|11|12Essa é uma verdadeira felicidade.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F71, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Bem, nos dois conseguimos o que|11queriamos...|11Entao aqui é onde nos separamos, ne?|BF", NULL);
EZTR_Basic_ReplaceText(0x1F72, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Sabe... ate que foi divertido.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F73, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05Bem... logo vai comecar o|11|01carnaval|05...|11|12Entao por que voce nao vai embora|11e cuida da sua vida?|11O resto de nos tem um carnaval pra|11aproveitar.|BF", NULL);
EZTR_Basic_ReplaceText(0x1F74, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05|00|05!|BF", NULL);
EZTR_Basic_ReplaceText(0x1F75, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05...Obrigado.|00|05|BF", NULL);
EZTR_Basic_ReplaceText(0x1FA4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce encontrou um destino terrivel,|11nao foi?|BF", NULL);
EZTR_Basic_ReplaceText(0x1FA5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu sou dono da|01 Loja de Mascaras Felizes|00.|11Viajo por todo lado em busca de|11mascaras...|11|12Durante minhas viagens, uma|11|01mascara|00 muito importante foi roubada|11por um duende na floresta.|11|12Entao aqui estou, perdido...|11E agora encontrei voce.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FA6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao pense que sou rude, mas estive|11te seguindo...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FA7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Pois eu conheco um jeito de te|11trazer de volta a sua |01forma original|00.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FA8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce conseguir recuperar o |01item|11precioso|00 que foi roubado de voce,|11eu vou te devolver ao |01normal|00.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FA9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Em troca...|11|12So peco que voce tambem recupere|11minha |01mascara preciosa|00 que o|11duende me roubou.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FAA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que?|11Nao é uma tarefa simples?|11|12Ora, para alguem como voce,|11nao deveria ser nada dificil.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FAB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Exceto que...|11|12Tem um detalhe...|11Sou um sujeito muito ocupado...|11|12E devo deixar este lugar em|11|01tres dias|00.|11|12Ficarei muito grato se voce|11trouxer de volta antes que|11meu |01tempo|00 aqui acabe...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FAC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas sim... Voce vai ficar bem.|11Vejo que é jovem e tem|11uma coragem tremenda.|11|12Tenho certeza que encontrara logo.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FAD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entao, estou contando com voce...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FAE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ora, ola...|11Voce encontrou aquele duende?|11|12Se conseguir recuperar o |01item|11precioso|00 que foi roubado de voce,|11eu o trarei de volta ao |01normal|00.|11|12Com certeza, voce devera encontra-lo|11logo.|11|12O tempo continua passando mesmo|11enquanto falamos. Restam apenas|11|01 |00.|11|12Por favor...|11Nao se esqueca da minha |01mascara preciosa|00.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FAF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Como voce se saiu?|11|12Voce vai ficar bem. Com certeza|11vai recuperar a |01Mascara de Majora|00.|11Eu acredito em voce.|11|12Ah, mas o tempo passa mesmo|11enquanto falamos...|11Restam apenas |01 |00.|11|12Ho, ho, ho...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce conseguiu recuperar seu|11|01item precioso|00 daquele duende?|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh! Oh! Ohhh!!!|11Voce tem! Voce tem!|11Voce tem! Voce tem!!!|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entao me escute. Por favor, toque esta|11musica que vou apresentar,|11e lembre-se bem dela...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Essa é uma melodia que |01cura|00 magia|11maligna e espiritos perturbados,|11transformando-os em |01mascaras|00.|11|12Tenho certeza de que sera util|11pra voce no futuro.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, sim. Eu lhe dou esta mascara em|11comemoracao deste dia.|11|12Nao tema, pois a magia foi|11selada dentro da mascara.|11|12Quando voce a usar, ira se|11transformar na forma que acabou|11de estar. Quando remove-la, voce|11voltara ao normal.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Agora, eu cumpri minha promessa|11com voce...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Entao, por favor, me de aquilo que|11|01voce prometeu|00...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Nao me diga...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Minha mascara...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FB9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Voce conseguiu...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FBA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "recupera-la... Nao foi?|BF", NULL);
EZTR_Basic_ReplaceText(0x1FBB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "O que voce fez comigo!!!|BF", NULL);
EZTR_Basic_ReplaceText(0x1FBC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Se voce deixar minha mascara la fora,|11algo terrivel vai acontecer!|BF", NULL);
EZTR_Basic_ReplaceText(0x1FBD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "A mascara que foi roubada de|11mim... |11Ela se chama |01Majora's Mask|00.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FBE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E um item amaldicoado da|11lenda que dizem ter sido usado por|11uma tribo antiga em seus|11rituais de magia negra.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FBF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Dizem que um poder maligno e cruel|11e concedido a quem|11usa aquela mascara.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FC0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Segundo a lenda...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FC1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "os problemas causados pela |01Majora's|11Mask|00 foram tao grandes...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FC2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "os antigos, temendo tal|11catastrofe, selaram a mascara nas|11sombras para sempre, impedindo seu|11mal uso.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FC3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Mas agora, aquela tribo da|11lenda desapareceu, entao ninguem|11sabe ao certo a verdadeira natureza|11do poder da mascara...|BF", NULL);
EZTR_Basic_ReplaceText(0x1FC4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Mas eu sinto.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FC5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Fiz de tudo para conseguir|11aquela mascara lendaria.|11Quando finalmente a obtive...|11|12Pude sentir o pressagio sombrio|11se formando. Era aquela|11sensacao ruim que faz seu cabelo|11se arrepiar.|BF", NULL);
EZTR_Basic_ReplaceText(0x1FC6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "E agora...|11aquele |01duende|00 esta com ela...|BF", NULL);
