EZTR_Basic_ReplaceText(0x2360, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah, meu Deus! A Máscara dos Noivos?|11Alguém se casou.|11|12Minha amiga vai se casar|11logo também...Logo...|BF", NULL);
EZTR_Basic_ReplaceText(0x2361, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aquela máscara?|11Ah, é verdade. A cidade deve|11ter seu carnaval em breve.|BF", NULL);
EZTR_Basic_ReplaceText(0x2362, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Dotour...|11|12Se eles te incomodarem, venha contar|11para a professora, ok?|BF", NULL);
EZTR_Basic_ReplaceText(0x2363, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "!!!|11O filho do prefeito?|11Não é bom fugir antes da|11cerimônia!|10...Eu queria poder ficar brava, mas meus|11próprios filhos fugiram com pressa|11antes do carnaval...|11|12Que pena! Eu poderia chorar!|19", NULL);
EZTR_Basic_ReplaceText(0x2364, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ei! Temos uma política de não usar máscaras...|11O quê??|11|12Eu não pensei que veria ninguém|11usando uma máscara assim de novo,|11mas aqui está uma.|11|12Então a esposa de Dotour está te fazendo|11procurar por ele com isso, hein?|11|12Não se parece em nada com ele,|11na verdade. Mas, por outro lado, acho que sim,|11então...hum...|11Ei...uh...eu quero que você vá embora agora.|19", NULL);
EZTR_Basic_ReplaceText(0x2365, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Olhe aqui!|11Não se intrometa com a minha querida|11Anju!!! Você tem medo dos meus punhos?|11Não vá encontrar esse Kafei!|19", NULL);
EZTR_Basic_ReplaceText(0x2366, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Eu o vi em algum lugar...|11Foi em algum lugar por aqui...|11|12Desculpe, estou ocupado.|19", NULL);
EZTR_Basic_ReplaceText(0x2367, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ohh, quantas pessoas vão|11me perguntar isso? Aquela senhora é tão|11persistente.|11|12Entããão, Kafei não quer|11romper seu noivado com|11Anju? Por que não deixá-lo? É isso|11que ele quer... |10Algumas pessoas...|BF", NULL);
EZTR_Basic_ReplaceText(0x2368, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Você é quem minha esposa contratou?|11Então Kafei ainda não...hmmm.|11|12Isso é um segredo, então não diga|11para minha esposa.|11|12Vá perguntar na Loja de Curiosidades,|11a loja na parte oeste da cidade|11que só abre à noite. Aquele|11cara é uma má influência para mim...|19", NULL);
EZTR_Basic_ReplaceText(0x2369, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Não sei onde ele está.|11Mesmo que soubesse, seria um|11segredo.|BF", NULL);
