EZTR_Basic_ReplaceText(0x28D3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Hoje à noite, às |0123:30|00, por favor, venha à|11nossa |01cozinha|00.|11Falaremos então...|BF", NULL);
EZTR_Basic_ReplaceText(0x28D4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Vou tentar encontrá-lo eu mesma.|11Pedir para outra pessoa fazer isso...|11Eu não consigo!|BF", NULL);
EZTR_Basic_ReplaceText(0x28D5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Não consigo encontrá-lo...|11Kafei...|11|12Onde...|11Me pergunto onde ele pode ter|11ido...|11|12E falta pouco tempo|11antes...|11do nosso casamento...|BF", NULL);
EZTR_Basic_ReplaceText(0x28D6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! ...Hum...Deixa pra lá!|BF", NULL);
EZTR_Basic_ReplaceText(0x28D7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Desculpe incomodá-lo tarde da|11noite. É sobre ele...Kafei.|19", NULL);
EZTR_Basic_ReplaceText(0x28D8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Recebi uma carta dele...|11|12Estranho...Não é?|11Receber uma carta de uma pessoa|11desaparecida...|11|12Mas não há absolutamente nenhum engano|11de que é dele!|11|12Está claro...para mim...|19", NULL);
EZTR_Basic_ReplaceText(0x28D9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Por favor!|19", NULL);
EZTR_Basic_ReplaceText(0x28DA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Aqui está minha carta.|11Por favor, coloque-a em uma caixa de correio.|11|12Quando for entregue...Quando ele|11receber minha carta... Você deve ser|11capaz de |01encontrá-lo|00!|11|12Por favor, diga a ele que Anju o|11está esperando.|11|12E por favor, depois de vê-lo...|11Me diga como ele estava.|11|12Estou com medo...Eu...Eu não consigo ir.|19", NULL);
EZTR_Basic_ReplaceText(0x28DB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Posso te pedir isso?|11 |11|02|02|C2Sim\n|11Não|BF", NULL);

EZTR_Basic_ReplaceText(0x28DC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Thank you...very much.|BF", NULL);
EZTR_Basic_ReplaceText(0x28DE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Please mail it immediately in the|11|01morning|00.|19", NULL);
EZTR_Basic_ReplaceText(0x28DF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Uh, umm...Aren't you going to|11take refuge?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Ah...Today's weather is|11unfortunate, isn't it?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I have decided to wait for him.|11I've made my promise...|11|12I'm fine with this.|11I believe him.|BF", NULL);
EZTR_Basic_ReplaceText(0x28E2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh...|11|12Did you...see him?|11|12...I'm sorry. It's too late, isn't it?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh...|11|12Did you...see him?|11|12...I'm sorry.|11It's probably too soon to ask...|BF", NULL);
EZTR_Basic_ReplaceText(0x28E4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh...|11|12Did you meet him?|19", NULL);
EZTR_Basic_ReplaceText(0x28E5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah!|19", NULL);
EZTR_Basic_ReplaceText(0x28E6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...It's from Kafei.|11Th...Th...Thank you...|11Very much!|BF", NULL);
EZTR_Basic_ReplaceText(0x28E7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Umm...What's that?|BF", NULL);
EZTR_Basic_ReplaceText(0x28E8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Excuse me.|11Have you seen a man in this|11area?|19", NULL);
EZTR_Basic_ReplaceText(0x28E9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "He looks like this...|19", NULL);
EZTR_Basic_ReplaceText(0x28EA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "He...disappeared about one month|11ago with his |01wedding ceremony|11mask|00.|19", NULL);
EZTR_Basic_ReplaceText(0x28EB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I'm...actually...afraid to meet him...|11|12and to hear the reason why he|11wanted to disappear...|11|12It might be because of... me...|19", NULL);
EZTR_Basic_ReplaceText(0x28EC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "There are only |01two days |00until the|11carnival...|11Should I wait?|11Kafei...|19", NULL);
EZTR_Basic_ReplaceText(0x28ED, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Ah! That mask...|11You're looking for him, too.|19", NULL);
EZTR_Basic_ReplaceText(0x28EE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I came here thinking I would look|11for him myself, but...|19", NULL);
EZTR_Basic_ReplaceText(0x28EF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05What a ramshackle inn. Is this|11room first-class? You can hear|11whoever's next door for cryin' out|11loud!|10Well, whatever...We're staying for|11free, so we can't expect much.|BF", NULL);
EZTR_Basic_ReplaceText(0x28F0, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05See, everything here is falling|11apart...You can hear the voices|11next door.|BF", NULL);
EZTR_Basic_ReplaceText(0x28F1, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "OK, Anju, we're leaving in the|11|01evening |00for the ranch.|11|12|01Cremia|00 will take us in. She is|11your best friend, right?|19", NULL);
EZTR_Basic_ReplaceText(0x28F2, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I wonder if Kafei is really at|11|01Cremia's|00 place...|19", NULL);
EZTR_Basic_ReplaceText(0x28F3, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "If Kafei is there, your mother will|11give him a smack.|11|12Besides, think about Cremia. She|11needs strength from a partner and|11business support from Madame|11Aroma.|10If Kafei really has run off with|11Cremia, she'll get both. Please|11don't be sad. How happy could |11you possibly be...|10marrying a man who runs off|11when he's about to be married?|11It would make your life unhappy|11...just like your mother's.|19", NULL);
EZTR_Basic_ReplaceText(0x28F4, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "But in the letter it said he |11definitely would come back...|19", NULL);
EZTR_Basic_ReplaceText(0x28F5, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Come back to what??|11Won't this town be crushed|11beneath the mono morning|11after tomorrow?|10Forget about that letter. For now,|11just try to survive.|11Everything else will follow...|19", NULL);
EZTR_Basic_ReplaceText(0x28F6, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Yes...|11Mother, Thank you.|19", NULL);
EZTR_Basic_ReplaceText(0x28F7, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Everyone will be taking refuge|11first thing in the morning. |11Everything was supposed to be all|11so...spirited...It's sad.|19", NULL);
EZTR_Basic_ReplaceText(0x28F8, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "We'll be going to Romani Ranch in|11the evening to take refuge. I think|11you should all hurry too.|BF", NULL);
EZTR_Basic_ReplaceText(0x28F9, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Perhaps I was wrong...|19", NULL);
EZTR_Basic_ReplaceText(0x28FA, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "But he said so...|11The morning of the ceremony...|11He'd come meet me in my room...|19", NULL);
EZTR_Basic_ReplaceText(0x28FB, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "And I promised him I would wait...|11But...already...it's too late, isn't it?|BF", NULL);
EZTR_Basic_ReplaceText(0x28FC, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Anju stayed in her room to wait|11for Kafei...|11|12It's foolish to believe a man|11like that.|11|12I too believed my husband would|11return out of the blue...|11|12Oh, Anju...|11That child's naive sense of trust|11may be my fault.|BF", NULL);
EZTR_Basic_ReplaceText(0x28FD, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "!!!|19", NULL);
EZTR_Basic_ReplaceText(0x28FE, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...I've been a little harsh on Anju.|11...But, it's fine this way.|11|12Right now, surviving is the|11important thing.|BF", NULL);
EZTR_Basic_ReplaceText(0x28FF, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I'm sorry.|11We're going to be taking refuge in|11the evening like the others.|11|12You should run, too.|11It seems it's going to fall|11tomorrow morning.|BF", NULL);
EZTR_Basic_ReplaceText(0x2900, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I'm sorry.|11Our rooms are filled.|BF", NULL);
EZTR_Basic_ReplaceText(0x2901, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Tortus, you're late...|11|12Tomorrow is another early day, so|11good night. I'll read you a story|11tomorrow.|BF", NULL);
EZTR_Basic_ReplaceText(0x2902, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Tortus.|11Did you finish helping father?|11|12Then let mother read you a story.|19", NULL);
EZTR_Basic_ReplaceText(0x2903, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Now, which story would you like|11to hear?|11|12|02I'll pass|11Carnival of Time |01 (2 hours)|11|02Four Giants |01(Til morning)|BF", NULL);
EZTR_Basic_ReplaceText(0x2904, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "The Carnival of Time, is it?|11|12The carnival is almost here, so it's|11good for you to learn its meaning.|11It's a little long, but I'll read it|11with some enthusiasm. Ahem...|10|11Each year, the season of harmony|11begins when the sun and moon|11are in alignment.|10Paying homage to the way that|11both nature and time are|11tirelessly in the process of |11progressing...|10the Carnival of Time is when the|11peoples of the four worlds|11celebrate that harmony and|11request fruitfulness for the year.|19", NULL);
EZTR_Basic_ReplaceText(0x2905, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "For ages, people have worn masks|11resembling the giants who are the|11gods of the four worlds.|11|12Now, it has become a custom for|11each person to bring a handmade|11mask to the Carnival of Time.|11|12It is said that if a couple united|11no day of the festival and|11dedicated a mask as a sign of|11their union, it would bring luck.|10The centerpiece of the carnival is|11the clock tower, and no eve|11of all the festivities, the doors to|11its roof are opened...|10From atop the clock tower roof, a|11ceremony to call the gods is held|11and an ancient song is sung.|11|12All of these festivities for the|11Carnival of Time are held so that|11we may ask the gods for a rich|11harvest in the year to come!|19", NULL);
EZTR_Basic_ReplaceText(0x2906, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "You did a good job!|11That's all for Tortus!|11|12Now, when does the clock tower|11roof open?|11|02|02|C2no eve of the festival\n|11I dunno|BF", NULL);
EZTR_Basic_ReplaceText(0x2907, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Well in that case, you try again|11with mother.|BF", NULL);
EZTR_Basic_ReplaceText(0x2908, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "You did a good job remembering.|11That's the boy I'm proud of.|19", NULL);
EZTR_Basic_ReplaceText(0x2909, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I'll give you some candy as a|11prize.|19", NULL);
EZTR_Basic_ReplaceText(0x290A, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, are you awake?|11|12I guess that story was a little|11boring for Tortus, wasn't it?|11|12Don't give up. Try again sometime.|BF", NULL);
EZTR_Basic_ReplaceText(0x290B, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|01The Four Giants|00, is it?|11|12This is quite long, but it is a good|11story for you to hear, so I'll read|11it with some extra gusto.|11Ahem...|10|11This tale's from long ago when all|11the people weren't separated into|11four worlds like they are now.|10In those times all the people lived|11together, and the four giants lived|11among them.|11|12no day of the festival that|11celebrates the harvest, the giants|11spoke to the people...|11|12|11|BF", NULL);
EZTR_Basic_ReplaceText(0x290C, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Now then...There was one who|11was shocked and saddened by|11all this.|11|12A little imp.|11|12The imp was a friend of the|11giants since before they had|11created the four worlds.|11|12|11 |11|11|12The childhood friend felt|11neglected, so he spread his anger|11across the four worlds.|11Repeatedly, he wronged all people.|10Overwhelmed with misfortune, the|11people sang the song of prayer to|11the giants who lived in each of|11the four compass directions.|10The giants heard their cry and|11responded with a roar.|11|10|11|10The imp was frightened and|11saddened.|11 |11He had lost his old friends.|10The imp returned to the heavens,|11and harmony was restored to the|11four worlds.|11|12And the people rejoiced and they|11worshiped the giants of the four|11worlds like gods. And they lived|11happily...ever after...|19", NULL);
EZTR_Basic_ReplaceText(0x290D, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Good job! Wasn't that fun,|11Tortus?|11|12What did the people do to call the|11giants?|11|02|02|C2Sing a song\n|11I dunno|BF", NULL);
EZTR_Basic_ReplaceText(0x290E, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, really?|11But you listened hard, so mother|11is happy.|19", NULL);
EZTR_Basic_ReplaceText(0x290F, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I'll give you some candy as your|11prize.|19", NULL);
EZTR_Basic_ReplaceText(0x2910, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "That's right, but you couldn't just|11sing that song anywhere.|11|12100 steps north,|11100 steps south,|11100 steps east,|11100 steps west.|10The spot at which those giants|11parted is right in the middle of|11this very town.|BF", NULL);
EZTR_Basic_ReplaceText(0x2911, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, are you awake?|11|12I guess that story was a little|11hard for Tortus.|11|12But don't give up. Try again later.|BF", NULL);
EZTR_Basic_ReplaceText(0x2912, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Oh, Tortus, are you ready?|11|12It's been a long time since we've|11had a picnic at Romani Ranch,|11hasn't it?|BF", NULL);
EZTR_Basic_ReplaceText(0x2913, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Isn't her bridal dress lovely?|11|12We promised each other when we|11were children that we'd marry on|11the day of the Carnival of Time.|11|12...But my promise...|11I couldn't keep it.|BF", NULL);
EZTR_Basic_ReplaceText(0x2914, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "I...I have met you before.|11|12What a familiar scent. Long, long|11ago...Yes. We were still young.|11We made a promise...|11Didn't we?|10The masks of the sun and the|11moon...|11|12We were to exchange them no|11day of the Carnival of Time...|BF", NULL);
EZTR_Basic_ReplaceText(0x2915, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Anju...|11I'm sorry I was late.|BF", NULL);
EZTR_Basic_ReplaceText(0x2916, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "...Welcome home.|BF", NULL);
EZTR_Basic_ReplaceText(0x2917, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "|05...Tee-hee! They're lovers, but they|11look just like a mother and child.|BF", NULL);
EZTR_Basic_ReplaceText(0x2918, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "Let us exchange the promised|11masks.|BF", NULL);
EZTR_Basic_ReplaceText(0x2919, EZTR_STANDARD_TEXT_BOX_I, 1, EZTR_ICON_NO_ICON, EZTR_NO_VALUE, EZTR_NO_VALUE, EZTR_NO_VALUE, true, "We have exchanged our oaths and|11have become a |01couple|00.|BF", NULL);
